class MyDataset(Dataset):
    def __init__(self, X, y):
        self.X = X
        self.y = y

    def __len__(self):
        return len(self.X)

    def __getitem__(self, idx):
        x = self.X[idx]
        # HWC numpy image -> CHW float tensor
        x = torch.tensor(x, dtype=torch.float32).permute(2, 0, 1) / 255.0

        # y was built from image arrays; convert to binary class index
        y = self.y[idx]
        if isinstance(y, np.ndarray):
            label = 1 if np.mean(y) > 0.5 else 0
        else:
            label = int(y)
        y = torch.tensor(label, dtype=torch.long)

        return x, y

